import React, { useState } from 'react';
import { Container, Row, Col, Input, Button, InputGroup, InputGroupText } from 'reactstrap';
import styled from 'styled-components';
import { FaFilter } from 'react-icons/fa'; // 새로운 아이콘

const SearchBarContainer = styled.div`
    display: flex;
    flex-direction: column;
    align-items: center;
    border: 2px solid transparent;
    border-radius: 25px;
    background: linear-gradient(#fff, #fff) padding-box, linear-gradient(to right, #ff00cc, #3333ff) border-box;
    padding: 10px;
    width: 100%;
    max-width: 800px; /* 최대 너비를 설정하여 길이를 조절 */
    position: relative;
    box-sizing: border-box;
    transition: all 0.3s ease-in-out;
`;

const SearchBarContent = styled.div`
    display: flex;
    width: 100%;
    justify-content: space-between;
    align-items: center;
`;

const CustomInput = styled(Input)`
    border: none;
    box-shadow: none;
    &:focus {
        outline: none;
        box-shadow: none;
    }
`;

const CustomButton = styled(Button)`
    background-color: #000;
    border: none;
    border-radius: 20px;
    padding: 10px 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    white-space: nowrap;
`;

const FilteringIcon = styled(FaFilter)`
    /* 새로운 아이콘 사용 */
    font-size: 24px;
    cursor: pointer;
`;

const FilterOptions = styled.div`
    width: 100%;
    padding: 20px;
    display: ${(props) => (props.show ? 'block' : 'none')};
    background: #fff;
    border-radius: 0 0 25px 25px;
    border-top: 1px solid #ccc;
    margin-top: 10px;
`;

const FilterSection = styled.div`
    margin-bottom: 20px;
`;

const SectionTitle = styled.h5`
    margin-bottom: 10px;
    font-weight: bold;
    text-align: left;
`;

const OptionList = styled.div`
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
`;

const OptionItem = styled.div`
    padding: 5px 10px;
    border: 1px solid #ccc;
    border-radius: 5px;
    cursor: pointer;
    background-color: ${(props) => (props.selected ? '#ddd' : '#fff')};
    &:hover {
        background-color: #f0f0f0;
    }
`;

const HeaderBanner = ({ onSearch }) => {
    const [searchQuery, setSearchQuery] = useState('');
    const [showFilters, setShowFilters] = useState(false);
    const [selectedCategories, setSelectedCategories] = useState(['전체']);
    const [selectedFollowers, setSelectedFollowers] = useState(['전체']);
    const [selectedGender, setSelectedGender] = useState('전체');
    const [selectedAge, setSelectedAge] = useState('전체');

    const handleSearch = () => {
        onSearch({
            searchQuery,
            categories: selectedCategories,
            followers: selectedFollowers,
            gender: selectedGender,
            age: selectedAge,
        });
    };

    const handleFilterClick = () => {
        setShowFilters(!showFilters);
    };

    const handleOptionClick = (option, setSelected, selected) => {
        if (option === '전체') {
            setSelected(['전체']);
        } else {
            const newSelected = selected.filter((item) => item !== '전체');
            if (newSelected.includes(option)) {
                setSelected(newSelected.filter((item) => item !== option));
            } else {
                setSelected([...newSelected, option]);
            }
        }
    };

    const handleSingleSelectClick = (option, setSelected) => {
        setSelected(option);
    };

    return (
        <div className="static-slider-head">
            <Container>
                <Row className="justify-content-center">
                    <Col lg="8" md="6" className="align-self-center text-center">
                        <h1 className="title">협차니</h1>
                        <SearchBarContainer>
                            <SearchBarContent>
                                <InputGroup style={{ flex: 1 }}>
                                    <CustomInput
                                        type="text"
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        placeholder="키워드 또는 해시태그를 입력해보세요."
                                        className="flex-grow-1"
                                    />
                                    {/* <InputGroupText onClick={handleFilterClick} style={{ background: 'none', border: 'none' }}>
                                        <FilteringIcon />
                                    </InputGroupText> */}
                                </InputGroup>
                                <CustomButton onClick={handleSearch}>
                                    <i className="fa fa-search" aria-hidden="true"></i> 검색
                                </CustomButton>
                            </SearchBarContent>
                            <FilterOptions show={showFilters}>
                                <FilterSection>
                                    <SectionTitle>카테고리</SectionTitle>
                                    <OptionList>
                                        {['전체', 'IT', '스포츠', '패션', '여행', '반려동물'].map((category) => (
                                            <OptionItem
                                                key={category}
                                                selected={selectedCategories.includes(category)}
                                                onClick={() =>
                                                    handleOptionClick(
                                                        category,
                                                        setSelectedCategories,
                                                        selectedCategories
                                                    )
                                                }
                                            >
                                                {category}
                                            </OptionItem>
                                        ))}
                                    </OptionList>
                                </FilterSection>
                                <FilterSection>
                                    <SectionTitle>팔로워</SectionTitle>
                                    <OptionList>
                                        {[
                                            '전체',
                                            '~5만명',
                                            '5~10만명',
                                            '10~30만명',
                                            '30~50만명',
                                            '50~70만명',
                                            '70~90만명',
                                            '90~150만명',
                                            '150만명~',
                                        ].map((follower) => (
                                            <OptionItem
                                                key={follower}
                                                selected={selectedFollowers.includes(follower)}
                                                onClick={() =>
                                                    handleOptionClick(follower, setSelectedFollowers, selectedFollowers)
                                                }
                                            >
                                                {follower}
                                            </OptionItem>
                                        ))}
                                    </OptionList>
                                </FilterSection>
                                <FilterSection>
                                    <SectionTitle>팔로워 성비</SectionTitle>
                                    <OptionList>
                                        {['전체', '여성', '남성'].map((gender) => (
                                            <OptionItem
                                                key={gender}
                                                selected={selectedGender === gender}
                                                onClick={() => handleSingleSelectClick(gender, setSelectedGender)}
                                            >
                                                {gender}
                                            </OptionItem>
                                        ))}
                                    </OptionList>
                                </FilterSection>
                                <FilterSection>
                                    <SectionTitle>팔로워 나이대</SectionTitle>
                                    <OptionList>
                                        {['전체', '13~17', '18~24', '25~34', '35~44', '45~54', '55~64', '65~'].map(
                                            (age) => (
                                                <OptionItem
                                                    key={age}
                                                    selected={selectedAge === age}
                                                    onClick={() => handleSingleSelectClick(age, setSelectedAge)}
                                                >
                                                    {age}
                                                </OptionItem>
                                            )
                                        )}
                                    </OptionList>
                                </FilterSection>
                            </FilterOptions>
                        </SearchBarContainer>
                    </Col>
                </Row>
            </Container>
        </div>
    );
};

export default HeaderBanner;
